    const now = performance.now();
    const elapsed = now - this._fpsLastSample;
    if (elapsed < 1000) return;
    const fps = (this._fpsFrames * 1000) / elapsed;
    this._fpsFrames = 0;
    this._fpsLastSample = now;
    this.onFps?.({ fps });
