// seed/poster-runtime.js (SEED-2, seed.md §4.4): ONE hidden canvas + ONE
// SeedRuntime for every still-frame render (cold-start poster, missing-
// poster gen) — thumbs.js lift: off-screen layout box, context-lost
// rebuild, retry-once, never cache a blank. Disposed after idle. Doesn't
// touch a playing seed's own runtime (it snapshots its own canvas).

const POSTER_W = 480;
const POSTER_H = 270; // 16:9, matches the host contract's aspect-ratio default
const IDLE_DISPOSE_MS = 10000;

let canvas = null;
let runtime = null;
let runtimeDead = false;
let idleTimer = null;

function ensure() {
  if (runtime || runtimeDead) return runtime;
  try {
    canvas = document.createElement('canvas');
    canvas.width = POSTER_W;
    canvas.height = POSTER_H;
    canvas.style.cssText =
      'position:fixed;left:-10000px;top:0;width:' + POSTER_W + 'px;height:' + POSTER_H + 'px;pointer-events:none;';
    canvas.setAttribute('aria-hidden', 'true');
    document.body.appendChild(canvas);
    runtime = new SeedRuntime(canvas);
    runtime.onContextLost = teardown;
  } catch {
    runtimeDead = true;
    if (canvas) canvas.remove();
    canvas = null;
  }
  return runtime;
}

function teardown() {
  if (runtime) {
    try {
      runtime.dispose();
    } catch {
      /* already gone */
    }
  }
  runtime = null;
  if (canvas) {
    canvas.remove();
    canvas = null;
  }
}

function scheduleIdleDispose() {
  clearTimeout(idleTimer);
  idleTimer = setTimeout(teardown, IDLE_DISPOSE_MS);
}

// Compile `glsl` and render one frame at `time` on the shared runtime;
// returns { ok:true, url } or { ok:false, code, log? }. Never throws.
function renderPosterFrame(glsl, time, _retried) {
  const rt = ensure();
  if (!rt) return { ok: false, code: 'no-webgl2' };
  const res = rt.setShader(glsl);
  if (!res.ok) return { ok: false, code: 'compile', log: res.log };
  rt.renderOnce(time);
  if (rt.isContextLost()) { // dead buffer -> blank PNG, never cache it
    teardown();
    if (!_retried) return renderPosterFrame(glsl, time, true);
    return { ok: false, code: 'no-webgl2' };
  }
  try {
    const url = canvas.toDataURL('image/png');
    scheduleIdleDispose();
    return { ok: true, url };
  } catch {
    return { ok: false, code: 'no-webgl2' };
  }
}

// Shader Garden — seed/element.js (SEED-2: courtesy ladder, V2_BLUEPRINT
// item 16, seed.md §2/§4/§10). Adds to SEED-1's kernel=-only skeleton:
// MAX_LIVE=4 + LRU posterize, the FPS ladder, the shared poster-runtime.js
// (one hidden canvas for every still-frame render), speed/t0/mouse/max-dpr
// live-retune attributes, sg-play/sg-pause. Deferred to SEED-3:
// src/href+unsafe, `interactive`, the attribution chip, `integrity`.
//
// import.meta.url must stay LAST in bake_seed.py's concat order — it
// becomes the baked seed@1.js's own URL, resolving sibling kernel JSON.


const IO_MARGIN = '200px';
const OFFSCREEN_POSTERIZE_MS = 30000;
const SCRIPT_DIR = new URL('.', import.meta.url);

// MAX_LIVE's value isn't frozen (seed.md §12 Q2) — only the budget +
// reason:'budget' existence is. 5 ~1 Hz samples approximates "5s sustained".
const MAX_LIVE = 4;
const FPS_LOW_STREAK = 5;
const FPS_DEGRADE_THRESHOLD = 24;
const FPS_POSTERIZE_THRESHOLD = 12;

const CSS = `
:host { display:block; aspect-ratio:16/9; contain:content; overflow:hidden; position:relative; background:#0b0d12; }
.wrap { container-type:size; position:absolute; inset:0; }
canvas, .poster { position:absolute; inset:0; width:100%; height:100%; display:block; border:0; }
canvas { object-fit:cover; }
canvas[hidden], .poster[hidden] { display:none; }
.poster { background:linear-gradient(135deg,#171b26,#2b3550) center/cover no-repeat; cursor:pointer; }
`;

// Constructable stylesheet, falls back to a per-root <style>.
let sheet;
function styleSheet() {
  if (sheet !== undefined) return sheet;
  try {
    sheet = new CSSStyleSheet();
    sheet.replaceSync(CSS);
  } catch {
    sheet = false;
  }
  return sheet;
}

// Per-URL fetch memoization; reject un-memoizes so a later retry refetches.
const kernelCache = new Map();
function fetchKernelJSON(url) {
  let p = kernelCache.get(url);
  if (p) return p;
  p = fetch(url)
    .then((res) => {
      if (!res.ok) {
        const err = new Error('kernel JSON request failed: ' + res.status);
        err.code = res.status === 404 ? 'not-found' : 'fetch';
        throw err;
      }
      return res.json();
    })
    .catch((err) => {
      kernelCache.delete(url);
      throw err;
    });
  kernelCache.set(url, p);
  return p;
}

// Shared IntersectionObserver — the only always-on listener pre-intersect.
const io =
  'IntersectionObserver' in window
    ? new IntersectionObserver((entries) => {
        for (const entry of entries) {
          if (entry.isIntersecting) entry.target._enter();
          else entry.target._leave();
        }
      }, { rootMargin: IO_MARGIN })
    : null;

const liveSeeds = new Set();

document.addEventListener('visibilitychange', () => {
  for (const s of liveSeeds) (document.hidden ? s._onHide() : s._onShow());
});
window.addEventListener('pagehide', () => {
  for (const s of liveSeeds) s._onPageHide();
});

const reducedMotionMQL = matchMedia('(prefers-reduced-motion: reduce)');
reducedMotionMQL.addEventListener('change', () => {
  for (const s of liveSeeds) s._onReducedMotionChange();
});

// MAX_LIVE budget (seed.md §4.3), page-wide, LRU-evicted by _lastEnterTime.
const playingSeeds = new Set();

function admitToLive(seed) {
  if (playingSeeds.has(seed)) return;
  if (playingSeeds.size >= MAX_LIVE) {
    let victim = null;
    let oldest = Infinity;
    for (const s of playingSeeds) {
      const t = s._lastEnterTime || 0;
      if (t < oldest) {
        oldest = t;
        victim = s;
      }
    }
    if (victim) {
      playingSeeds.delete(victim);
      victim._emit('sg-pause', { reason: 'budget' }); // seed.md §4.3
      victim._posterize('budget');
    }
  }
  playingSeeds.add(seed);
}

function releaseLive(seed) {
  playingSeeds.delete(seed);
}

/** `<shader-seed>` — seed.md §2. This build covers the kernel= tier (§10
 * Stages 1-2); SEED-3's src/href/unsafe foreign-source tier is not here. */
class ShaderSeed extends HTMLElement {
  constructor() {
    super();
    this._built = false;
    this._state = 'idle';
    this._runtime = null;
    this._kernelData = null;
    this._isIntersecting = false;
    this._pausedByHidden = false;
    this._lossCount = 0;
    this._offTimer = null;
    this._pendingPlayReason = null;
    this._lastEnterTime = 0;
    this._lastFps = 0;
    this._dprDegraded = false;
    this._lowFpsStreak24 = 0;
    this._lowFpsStreak12 = 0;
  }

  static get observedAttributes() {
    return ['kernel', 'speed', 't0', 'mouse', 'max-dpr'];
  }

  // lifecycle

  connectedCallback() {
    if (!this._built) this._build();
    liveSeeds.add(this);
    if (io) io.observe(this);
    else this._enter(); // no IO support: degrade to immediate start
  }

  disconnectedCallback() {
    liveSeeds.delete(this);
    if (io) io.unobserve(this);
    this._isIntersecting = false;
    clearTimeout(this._offTimer);
    this._offTimer = null;
    this._teardown();
    this._state = 'idle';
  }

  attributeChangedCallback(name, oldVal, newVal) {
    if (!this._built || oldVal === newVal) return;
    if (name !== 'kernel') {
      this._retune(name);
      return;
    }
    clearTimeout(this._offTimer);
    this._offTimer = null;
    this._teardown();
    this._state = 'idle';
    this._kernelData = null;
    this._pendingPlayReason = null;
    this._resetPosterToDefault();
    if (this._isIntersecting) this._enter();
  }

  // imperative API (seed.md §2.2)

  play() {
    this._playRequested('api');
  }

  pause() {
    this._internalPause('api');
  }

  posterize() {
    this._posterize('api');
  }

  reset() {
    if (!this._runtime) return;
    const c = this._runtime.getClock();
    c.time = this._t0();
    c.frame = 0;
  }

  get state() {
    return this._state;
  }

  get backend() {
    return this._runtime ? 'webgl2' : null;
  }

  get fps() {
    return this._lastFps || 0;
  }

  // shadow DOM

  _build() {
    this._built = true;
    const root = this.attachShadow({ mode: 'open' });
    const s = styleSheet();
    if (s) {
      root.adoptedStyleSheets = [s];
    } else {
      const style = document.createElement('style');
      style.textContent = CSS;
      root.appendChild(style);
    }

    const wrap = document.createElement('div');
    wrap.className = 'wrap';

    const canvas = document.createElement('canvas');
    canvas.setAttribute('part', 'canvas');
    canvas.hidden = true;

    const poster = document.createElement('div');
    poster.className = 'poster';
    poster.setAttribute('part', 'poster');
    poster.addEventListener('click', () => this._playRequested('gesture'));

    wrap.append(canvas, poster);
    root.appendChild(wrap);

    this._wrap = wrap;
    this._canvas = canvas;
    this._poster = poster;
    this._resetPosterToDefault();
  }

  _resetPosterToDefault() {
    const posterAttr = this.getAttribute('poster');
    this._poster.style.backgroundImage = posterAttr ? `url("${posterAttr}")` : '';
    this._poster.hidden = false;
    this._canvas.hidden = true;
  }

  // laziness (seed.md §4.1)

  _enter() {
    this._isIntersecting = true;
    this._lastEnterTime = performance.now();
    clearTimeout(this._offTimer);
    this._offTimer = null;
    if (this._state === 'idle') {
      this._load();
      return;
    }
    if (this._state === 'paused' && this._shouldAutoplay()) {
      this._playRuntime('visible');
      return;
    }
    if (this._state === 'poster' && !this._runtime && this._kernelData && this._shouldAutoplay()) {
      this._bootLive(this._kernelData.glsl, 'visible');
    }
  }

  _leave() {
    this._isIntersecting = false;
    if (this._state === 'playing') this._internalPause('visible');
    clearTimeout(this._offTimer);
    this._offTimer = setTimeout(() => this._posterize('budget'), OFFSCREEN_POSTERIZE_MS);
  }

  _onHide() {
    if (this._state === 'playing') {
      this._internalPause('hidden');
      this._pausedByHidden = true;
    }
  }

  _onShow() {
    if (this._pausedByHidden) {
      this._pausedByHidden = false;
      if (this._isIntersecting) this._playRuntime('visible');
    }
  }

  _onPageHide() {
    this._teardown(); // bfcache safety: dispose without a snapshot
  }

  _onReducedMotionChange() {
    if (reducedMotionMQL.matches && this._state === 'playing') {
      this._showPosterFrame('reduced-motion');
    }
  }

  // attribute reads

  _autoplay() {
    const v = this.getAttribute('autoplay');
    return v === 'click' || v === 'off' ? v : 'visible';
  }

  _shouldAutoplay() {
    return this._autoplay() === 'visible' && !reducedMotionMQL.matches;
  }

  _kernelUrl(id) {
    const gardenAttr = this.getAttribute('garden');
    const base = gardenAttr ? new URL(gardenAttr, location.href) : SCRIPT_DIR;
    return new URL(id + '.json', base).href;
  }

  _t0() {
    const v = Number(this.getAttribute('t0'));
    return Number.isFinite(v) ? v : 0;
  }

  _speed() {
    const v = Number(this.getAttribute('speed'));
    return Number.isFinite(v) ? v : 1;
  }

  _mouseVec() {
    const raw = this.getAttribute('mouse');
    if (!raw) return null;
    const parts = raw.split(',').map(Number);
    if (parts.length !== 4 || parts.some((n) => !Number.isFinite(n))) return null;
    return parts;
  }

  _maxDpr() {
    const v = Number(this.getAttribute('max-dpr'));
    const dpr = Number.isFinite(v) ? v : 1.5;
    return Math.min(2, Math.max(0.5, dpr));
  }

  // live retune (§2.1): never rebuild

  _retune(name) {
    if (name === 'speed') this._retuneSpeed();
    else if (name === 't0') this._retuneT0();
    else if (name === 'mouse') this._retuneMouse();
    else if (name === 'max-dpr') this._retuneMaxDpr();
  }

  _retuneSpeed() {
    if (!this._runtime) return;
    const c = this._runtime.getClock();
    const speed = this._speed();
    c.speed = speed;
    if (speed === 0) {
      c.time = this._t0();
      c.dt = 0;
    }
  }

  // A seed already settled on its own rendered still (no `poster` override)
  // redraws at the new t0. A currently playing seed is left alone — no
  // clock jump on an attribute mutation (judgment call, SEED-2).
  _retuneT0() {
    if (this._state === 'poster' && !this.getAttribute('poster') && this._kernelData) {
      this._showPosterFrame('api');
    }
  }

  _retuneMouse() {
    if (!this._runtime) return;
    this._runtime.getClock().mouse = this._mouseVec() || [0, 0, 0, 0];
  }

  _retuneMaxDpr() {
    if (this._runtime) this._runtime.setDprCap(this._maxDpr());
  }

  _applyLiveAttrs(runtime) {
    const c = runtime.getClock();
    c.speed = this._speed();
    if (c.speed === 0) c.time = this._t0();
    c.mouse = this._mouseVec() || [0, 0, 0, 0];
    runtime.setDprCap(this._maxDpr());
    runtime.onFps = (sample) => this._onFpsSample(sample);
  }

  // FPS ladder

  _onFpsSample({ fps }) {
    this._lastFps = fps;
    if (fps < FPS_DEGRADE_THRESHOLD) this._lowFpsStreak24 = (this._lowFpsStreak24 || 0) + 1;
    else this._lowFpsStreak24 = 0;
    if (!this._dprDegraded && this._lowFpsStreak24 >= FPS_LOW_STREAK) {
      this._dprDegraded = true;
      this._runtime?.setDprScale(0.5);
    }
    // "<12fps for 5s AFTER that" — only evaluated once already degraded.
    if (this._dprDegraded) {
      if (fps < FPS_POSTERIZE_THRESHOLD) this._lowFpsStreak12 = (this._lowFpsStreak12 || 0) + 1;
      else this._lowFpsStreak12 = 0;
      if (this._lowFpsStreak12 >= FPS_LOW_STREAK) {
        this._emit('sg-pause', { reason: 'fps' });
        this._posterize('budget');
      }
    }
  }

  // load / compile / play

  async _load() {
    const kernelId = this.getAttribute('kernel');
    if (!kernelId) {
      this._fail('no-source', 'missing kernel attribute (src=/href= are SEED-3)');
      return;
    }
    this._state = 'loading';
    let data;
    try {
      data = await fetchKernelJSON(this._kernelUrl(kernelId));
    } catch (err) {
      this._fail(err.code || 'fetch', String((err && err.message) || err));
      return;
    }
    if (!this.isConnected) return; // removed mid-fetch
    this._kernelData = data;
    this._start(data);
  }

  _start(data) {
    const reason = this._pendingPlayReason || (this._shouldAutoplay() ? 'visible' : null);
    this._pendingPlayReason = null;
    if (reason) {
      this._bootLive(data.glsl, reason);
      return;
    }
    // The shared poster runtime's compile IS this baked kernel's compile
    // check — a failure here is a garden bug (seed.md §8), not a typo.
    const res = renderPosterFrame(data.glsl, this._t0());
    if (!res.ok) {
      this._fail(res.code, res.log || 'compile failed');
      return;
    }
    this._emit('sg-ready', { kernelId: data.id, backend: 'webgl2', title: data.title });
    this._settlePoster(res.url, reducedMotionMQL.matches ? 'reduced-motion' : 'api');
  }

  _createRuntime(glsl) {
    let runtime;
    try {
      runtime = new SeedRuntime(this._canvas);
    } catch (err) {
      return { ok: false, code: 'no-webgl2', log: String((err && err.message) || err) };
    }
    const res = runtime.setShader(glsl);
    if (!res.ok) {
      runtime.dispose();
      return { ok: false, code: 'compile', log: res.log };
    }
    return { ok: true, runtime };
  }

  _bootLive(glsl, reason) {
    const built = this._createRuntime(glsl);
    if (!built.ok) {
      this._fail(built.code, built.log || '');
      return;
    }
    this._runtime = built.runtime;
    this._runtime.onContextLost = () => this._onContextLost();
    this._lossCount = 0;
    this._lastFps = 0;
    this._dprDegraded = false;
    this._lowFpsStreak24 = 0;
    this._lowFpsStreak12 = 0;
    this._applyLiveAttrs(this._runtime);
    this._emit('sg-ready', { kernelId: this._kernelData.id, backend: 'webgl2', title: this._kernelData.title });
    this._playRuntime(reason);
  }

  _playRequested(reason) {
    if (this._state === 'idle') {
      this._pendingPlayReason = reason;
      this._load();
      return;
    }
    if (!this._runtime) {
      if (!this._kernelData) {
        this._pendingPlayReason = reason;
        this._load();
        return;
      }
      this._bootLive(this._kernelData.glsl, reason);
      return;
    }
    this._playRuntime(reason);
  }

  _playRuntime(reason) {
    const wasPlaying = this._state === 'playing';
    this._canvas.hidden = false;
    this._poster.hidden = true;
    this._runtime.start();
    this._state = 'playing';
    admitToLive(this);
    if (!wasPlaying) this._emit('sg-play', { reason });
  }

  _internalPause(reason) {
    if (this._runtime && this._state === 'playing') {
      this._runtime.stop();
      this._state = 'paused';
      releaseLive(this);
      this._emit('sg-pause', { reason });
    }
  }

  // Used by _start (cold), _posterize (live snapshot), _showPosterFrame.
  _settlePoster(url, reason) {
    if (url) this._poster.style.backgroundImage = `url("${url}")`;
    this._poster.hidden = false;
    this._canvas.hidden = true;
    this._state = 'poster';
    this._emit('sg-poster', { reason });
  }

  // Reduced-motion/cold-start/t0-retune leg: always renders at t0 via the
  // ONE shared hidden canvas (§4.4), not this element's own GL context.
  // Note: the shared runtime renders with iMouse=[0,0,0,0] always — `mouse`
  // pins LIVE playback only, not the static still (scope cut).
  _showPosterFrame(reason) {
    this._teardown();
    const data = this._kernelData;
    let url = null;
    if (data) {
      const res = renderPosterFrame(data.glsl, this._t0());
      if (res.ok) url = res.url; // else: keep the prior poster, never blank
    }
    this._settlePoster(url, reason);
  }

  // Snapshots the LIVE canvas's CURRENT frame (not t0) and disposes the GL
  // context. Off-screen timer, MAX_LIVE eviction, FPS ladder, posterize().
  _posterize(reason) {
    this._offTimer = null;
    if (!this._runtime) {
      releaseLive(this);
      if (this._state === 'paused') this._state = 'poster';
      return;
    }
    this._capturePoster(this._runtime);
    this._teardown();
    this._canvas.hidden = true;
    this._poster.hidden = false;
    this._state = 'poster';
    this._emit('sg-poster', { reason });
  }

  _capturePoster(rt) {
    if (rt.isContextLost()) return; // dead buffer -> blank PNG, never cache
    try {
      const url = rt.canvas.toDataURL('image/png');
      this._poster.style.backgroundImage = `url("${url}")`;
    } catch {
      /* tainted canvas or unsupported — keep whatever poster was showing */
    }
  }

  _onContextLost() {
    this._lossCount += 1;
    this._teardown();
    this._canvas.hidden = true;
    this._poster.hidden = false;
    // One silent rebuild; a second loss posterizes for good (no-retry for
    // `unsafe` sources is SEED-3's concern, not this tier).
    if (this._lossCount <= 1 && this._kernelData) {
      this._bootLive(this._kernelData.glsl, 'api');
      return;
    }
    this._state = 'poster';
    this._emit('sg-error', { code: 'context-lost', message: 'WebGL context lost' });
    this._emit('sg-poster', { reason: 'error' });
  }

  _teardown() {
    releaseLive(this);
    if (this._runtime) {
      try {
        this._runtime.dispose();
      } catch {
        /* already gone */
      }
      this._runtime = null;
    }
  }

  _fail(code, message) {
    this._pendingPlayReason = null;
    releaseLive(this);
    this._state = 'error';
    if (this._canvas) this._canvas.hidden = true;
    if (this._poster) this._poster.hidden = false;
    this._emit('sg-error', { code, message });
    this._emit('sg-poster', { reason: 'error' });
  }

  _emit(name, detail) {
    this.dispatchEvent(new CustomEvent(name, { detail, bubbles: true, composed: true }));
  }
}

if (!customElements.get('shader-seed')) customElements.define('shader-seed', ShaderSeed);
